package net.officefloor.hq.app.people;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.JoinTable;
import jakarta.persistence.ManyToMany;
import jakarta.persistence.Table;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person on the list: a name and whole-number "alpha", "beta" and "gamma" (each absent until
 * given), and the derived "thrust" (alpha × beta), "drift" (gamma − alpha) and "momentum"
 * (thrust + 3 × drift), which are absent until all three raw values are given. A person may have
 * any number of "patrons": other people on the list, whose thrust added together is the person's
 * "backing". A person belongs to one sheet (null for the unnamed sheet) and is numbered within it, so sheets never share people. "Net" is momentum plus backing (backing counted as zero without patrons). */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The person's id within their sheet; the id the user and the API see. */
    @Column(name = "local_id")
    private Long localId;

    private String name;

    private Integer alpha;

    private Integer beta;

    private Integer gamma;

    /** The id of the sheet the person belongs to; null for the unnamed sheet. */
    @Column(name = "sheet_id")
    private String sheetId;

    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"),
            inverseJoinColumns = @JoinColumn(name = "patron_id"))
    private Set<Person> patrons = new HashSet<>();

    protected Person() {
    }

    public Person(String sheetId, long localId, String name, Integer alpha, Integer beta, Integer gamma) {
        this.sheetId = sheetId;
        this.localId = localId;
        this.name = name;
        this.alpha = alpha;
        this.beta = beta;
        this.gamma = gamma;
    }

    public Long getId() {
        return id;
    }

    public Long getLocalId() {
        return localId;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public Integer getAlpha() {
        return alpha;
    }

    public void setAlpha(Integer alpha) {
        this.alpha = alpha;
    }

    public Integer getBeta() {
        return beta;
    }

    public void setBeta(Integer beta) {
        this.beta = beta;
    }

    public Integer getGamma() {
        return gamma;
    }

    public void setGamma(Integer gamma) {
        this.gamma = gamma;
    }

    /** The patrons, sorted by name. */
    public List<Person> getPatrons() {
        return patrons.stream()
                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
                .toList();
    }

    public void setPatrons(Set<Person> patrons) {
        this.patrons = new HashSet<>(patrons);
    }

    /** The derived values exist only once alpha, beta and gamma are all given. */
    private boolean complete() {
        return alpha != null && beta != null && gamma != null;
    }

    /** Thrust is alpha multiplied by beta; absent until alpha, beta and gamma are all given. */
    public Integer getThrust() {
        return complete() ? alpha * beta : null;
    }

    /** Drift is gamma minus alpha; absent until alpha, beta and gamma are all given. */
    public Integer getDrift() {
        return complete() ? gamma - alpha : null;
    }

    /** Momentum is thrust plus three times drift; absent while either is absent. */
    public Integer getMomentum() {
        Integer thrust = getThrust();
        Integer drift = getDrift();
        return thrust == null || drift == null ? null : thrust + 3 * drift;
    }

    /** Backing is the sum of the patrons' thrust; absent without patrons or while any patron's thrust is absent. */
    public Integer getBacking() {
        if (patrons.isEmpty()) {
            return null;
        }
        int sum = 0;
        for (Person patron : patrons) {
            Integer thrust = patron.getThrust();
            if (thrust == null) {
                return null;
            }
            sum += thrust;
        }
        return sum;
    }

    /** Net is momentum plus backing, counting backing as zero without patrons; absent with momentum, or with a patron whose thrust is absent. */
    public Integer getNet() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        if (patrons.isEmpty()) {
            return momentum;
        }
        Integer backing = getBacking();
        return backing == null ? null : momentum + backing;
    }
    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
    public String getTier() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
    }
}
package net.officefloor.hq.app;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.context.annotation.Profile;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/**
 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
 * ARRANGE data; they ASSERT only through the UI.
 */
@Profile("e2e")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private static final Set<String> PERSON_FIELDS = Set.of("id", "name", "alpha", "beta", "gamma");

    private static final Set<String> PATRON_FIELDS = Set.of("personId", "patronId");

    private static final Set<String> SHEET_FIELDS = Set.of("id", "people", "patrons");

    private final Audit audit;
    private final JdbcTemplate jdbc;

    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
        this.audit = audit;
        this.jdbc = jdbc;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    @Transactional
    public void reset() {
        audit.clear();
        // Person is referenced by its patrons, so delete rather than truncate.
        jdbc.update("DELETE FROM person_patron");
        jdbc.update("DELETE FROM person");
        jdbc.update("DELETE FROM sheet");
        jdbc.execute("ALTER TABLE person ALTER COLUMN id RESTART WITH 1");
    }

    /**
     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
     */
    @PostMapping("/seed")
    @Transactional
    public void seed(@RequestBody Map<String, Object> fixture) {
        for (String key : fixture.keySet()) {
            if (!key.equals("people") && !key.equals("patrons") && !key.equals("sheets")) {
                throw badRequest("unknown fixture key: " + key);
            }
        }
        // People and patrons at the top level are on the unnamed sheet.
        seedSheet(null, fixture.get("people"), fixture.get("patrons"), "");
        for (Map<String, Object> sheet : rows(fixture.get("sheets"), "sheets")) {
            for (String field : sheet.keySet()) {
                if (!SHEET_FIELDS.contains(field)) {
                    throw badRequest("cannot store sheets." + field);
                }
            }
            if (!(sheet.get("id") instanceof String id) || id.isBlank()) {
                throw badRequest("sheets.id is required");
            }
            jdbc.update("INSERT INTO sheet (id) VALUES (?)", id);
            seedSheet(id, sheet.get("people"), sheet.get("patrons"), "sheets.");
        }
    }

    private static String sheetWhere(String sheetId) {
        return sheetId == null ? "sheet_id IS NULL" : "sheet_id = ?";
    }

    private static Object[] sheetArgs(String sheetId, Object... more) {
        List<Object> args = new ArrayList<>();
        if (sheetId != null) {
            args.add(sheetId);
        }
        args.addAll(List.of(more));
        return args.toArray();
    }

    private long nextLocalId(String sheetId) {
        return jdbc.queryForObject("SELECT COALESCE(MAX(local_id), 0) + 1 FROM person WHERE " + sheetWhere(sheetId),
                Long.class, sheetArgs(sheetId));
    }

    /** The internal key of the person with an id on a sheet; refuses an id the sheet does not have. */
    private long internalId(String sheetId, long localId, String field) {
        List<Long> ids = jdbc.queryForList("SELECT id FROM person WHERE " + sheetWhere(sheetId) + " AND local_id = ?",
                Long.class, sheetArgs(sheetId, localId));
        if (ids.isEmpty()) {
            throw badRequest(field + " " + localId + " is not a person on the sheet");
        }
        return ids.get(0);
    }

    /** Inserts one sheet's people and then their patrons; a null sheet id is the unnamed sheet. */
    private void seedSheet(String sheetId, Object peopleRows, Object patronRows, String prefix) {
        for (Map<String, Object> row : rows(peopleRows, prefix + "people")) {
            for (String field : row.keySet()) {
                if (!PERSON_FIELDS.contains(field)) {
                    throw badRequest("cannot store " + prefix + "people." + field);
                }
            }
            if (!(row.get("name") instanceof String name)) {
                throw badRequest(prefix + "people.name is required");
            }
            Integer alpha = integer(row.get("alpha"), prefix + "people.alpha");
            Integer beta = integer(row.get("beta"), prefix + "people.beta");
            Integer gamma = integer(row.get("gamma"), prefix + "people.gamma");
            // A person's id is their id within the sheet; the internal key is generated.
            Integer localId = integer(row.get("id"), prefix + "people.id");
            jdbc.update("INSERT INTO person (sheet_id, local_id, name, alpha, beta, gamma) VALUES (?, ?, ?, ?, ?, ?)",
                    sheetId, localId != null ? localId : nextLocalId(sheetId), name, alpha, beta, gamma);
        }
        // Patrons link people by id, so add them once every person exists.
        for (Map<String, Object> row : rows(patronRows, prefix + "patrons")) {
            for (String field : row.keySet()) {
                if (!PATRON_FIELDS.contains(field)) {
                    throw badRequest("cannot store " + prefix + "patrons." + field);
                }
            }
            Integer personId = integer(row.get("personId"), prefix + "patrons.personId");
            Integer patronId = integer(row.get("patronId"), prefix + "patrons.patronId");
            if (personId == null || patronId == null) {
                throw badRequest(prefix + "patrons rows need personId and patronId");
            }
            jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)",
                    internalId(sheetId, personId, prefix + "patrons.personId"),
                    internalId(sheetId, patronId, prefix + "patrons.patronId"));
        }
    }

    /**
     * Read back what is stored, in the same shape and with the same field names the fixtures use,
     * so earlier checkpoints' test data can be replayed and checked (AGENTS.md §4.3, §4.4). The
     * unnamed sheet's people are at the top level; each named sheet nests its own.
     */
    @GetMapping("/fixture")
    public Map<String, Object> fixture() {
        Map<String, Object> out = new LinkedHashMap<>(sheetContents(null));
        List<Map<String, Object>> sheets = new ArrayList<>();
        for (String id : jdbc.queryForList("SELECT id FROM sheet ORDER BY id", String.class)) {
            Map<String, Object> sheet = new LinkedHashMap<>();
            sheet.put("id", id);
            sheet.putAll(sheetContents(id));
            sheets.add(sheet);
        }
        out.put("sheets", sheets);
        return out;
    }

    private Map<String, Object> sheetContents(String sheetId) {
        String where = sheetId == null ? "p.sheet_id IS NULL" : "p.sheet_id = ?";
        Object[] args = sheetId == null ? new Object[0] : new Object[] {sheetId};
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("people", jdbc.queryForList("SELECT local_id AS \"id\", name AS \"name\", alpha AS \"alpha\", "
                + "beta AS \"beta\", gamma AS \"gamma\" FROM person p WHERE " + where + " ORDER BY local_id", args));
        out.put("patrons", jdbc.queryForList("SELECT p.local_id AS \"personId\", o.local_id AS \"patronId\" "
                + "FROM person_patron pp JOIN person p ON p.id = pp.person_id JOIN person o ON o.id = pp.patron_id "
                + "WHERE " + where + " ORDER BY p.local_id, o.local_id", args));
        return out;
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> rows(Object value, String key) {
        if (value == null) {
            return List.of();
        }
        if (!(value instanceof List<?> list) || !list.stream().allMatch(r -> r instanceof Map)) {
            throw badRequest(key + " must be a list of rows");
        }
        return (List<Map<String, Object>>) list;
    }

    private static Integer integer(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number n && n.doubleValue() == Math.rint(n.doubleValue())) {
            return n.intValue();
        }
        if (value instanceof String s && s.matches("-?\\d+")) {
            return Integer.valueOf(s);
        }
        throw badRequest(field + " must be a whole number, got " + value);
    }

    private static ResponseStatusException badRequest(String message) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
    }
}
package net.officefloor.hq.app.people;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma,
            Integer thrust, Integer drift, Integer momentum, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile) {
        static PersonView of(Person p, Map<Long, Integer> ranks) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(),
                    p.getThrust(), p.getDrift(), p.getMomentum(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()));
        }
    }

    /**
     * A rank as a percentile of the ranked people: the best 100, the worst 0, evenly spread between
     * by rank and rounded to a whole number. A lone ranked person is 100; unranked has none.
     */
    static Integer percentile(Integer rank, int ranked) {
        if (rank == null) {
            return null;
        }
        if (ranked <= 1) {
            return 100;
        }
        return (int) Math.round((ranked - rank) * 100.0 / (ranked - 1));
    }

    /** Highest momentum first; equal momentum by higher alpha, then by name, earlier in the alphabet first. */
    private static final Comparator<Person> RANK_ORDER = Comparator
            .comparing(Person::getMomentum, Comparator.reverseOrder())
            .thenComparing(Person::getAlpha, Comparator.nullsLast(Comparator.reverseOrder()))
            .thenComparing(Person::getName)
            .thenComparing(Person::getLocalId);

    public record PatronView(Long id, String name) {
    }

    public record NewPerson(@NotBlank String name, Integer alpha, Integer beta, Integer gamma) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(@RequestParam(required = false) String sheet) {
        List<Person> people = service.list(sheetId(sheet));
        Map<Long, Integer> ranks = ranks(people);
        return people.stream().map(p -> PersonView.of(p, ranks)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@RequestParam(required = false) String sheet, @Valid @RequestBody NewPerson person) {
        return view(sheetId(sheet), service.add(sheetId(sheet), person.name(), person.alpha(), person.beta(), person.gamma()));
    }

    /**
     * Sets, on the person with this id on the request's sheet, whichever of alpha, beta, gamma and
     * patronIds (a list of ids on that sheet) the body names; a null value clears it.
     */
    @PatchMapping("/{id}")
    public PersonView update(@RequestParam(required = false) String sheet, @PathVariable long id,
            @RequestBody Map<String, Object> update) {
        String sheetId = sheetId(sheet);
        Optional<Person> person = service.find(sheetId, id);
        if (update.containsKey("alpha")) {
            person = service.setAlpha(sheetId, id, integer(update.get("alpha")));
        }
        if (update.containsKey("beta")) {
            person = service.setBeta(sheetId, id, integer(update.get("beta")));
        }
        if (update.containsKey("gamma")) {
            person = service.setGamma(sheetId, id, integer(update.get("gamma")));
        }
        if (update.containsKey("patronIds")) {
            List<Long> patronIds = new ArrayList<>();
            if (update.get("patronIds") instanceof List<?> ids) {
                for (Object patronId : ids) {
                    patronIds.add(integer(patronId).longValue());
                }
            } else if (update.get("patronIds") != null) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "patronIds must be a list");
            }
            try {
                person = service.setPatrons(sheetId, id, patronIds);
            } catch (IllegalArgumentException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
            }
        }
        return person.map(p -> view(sheetId, p))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }

    /** A person's view, ranked among the people on their sheet. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, ranks(service.list(sheetId)));
    }

    /**
     * Each person's rank by local id: 1 for the highest momentum, then 2, 3, ... with equal momentum
     * ordered by higher alpha, then by name. People without a momentum are not ranked.
     */
    private static Map<Long, Integer> ranks(List<Person> people) {
        List<Person> ranked = people.stream().filter(p -> p.getMomentum() != null).sorted(RANK_ORDER).toList();
        Map<Long, Integer> ranks = new HashMap<>();
        for (int i = 0; i < ranked.size(); i++) {
            ranks.put(ranked.get(i).getLocalId(), i + 1);
        }
        return ranks;
    }

    /** The sheet named by the request, trimmed; blank or absent means the unnamed sheet. */
    private static String sheetId(String sheet) {
        return sheet == null || sheet.isBlank() ? null : sheet.trim();
    }

    private static Integer integer(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer i) {
            return i;
        }
        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "expected a whole number, got " + value);
    }
}
package net.officefloor.hq.app.people;

import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PersonService {

    private final PersonRepository people;

    private final SheetRepository sheets;

    private final Audit audit;

    public PersonService(PersonRepository people, SheetRepository sheets, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    /** The people on a sheet; a null sheet id is the unnamed sheet. */
    public List<Person> list(String sheetId) {
        return people.findBySheetId(sheetId, Sort.by("localId"));
    }

    /** Whether a named sheet has been stored. */
    @Transactional(readOnly = true)
    public boolean sheetExists(String sheetId) {
        return sheets.existsById(sheetId);
    }

    /** Opens a named sheet, storing it as a new empty sheet when it does not exist yet. */
    @Transactional
    public Sheet openSheet(String sheetId) {
        return sheets.findById(sheetId).orElseGet(() -> sheets.save(new Sheet(sheetId)));
    }

    /** The person with an id on a sheet; a null sheet id is the unnamed sheet. */
    @Transactional(readOnly = true)
    public Optional<Person> find(String sheetId, long id) {
        return people.findBySheetIdAndLocalId(sheetId, id);
    }

    @Transactional
    /** Adds a person to a sheet (null for the unnamed sheet), creating the sheet on first use. */
    public Person add(String sheetId, String name, Integer alpha, Integer beta, Integer gamma) {
        if (sheetId != null && !sheets.existsById(sheetId)) {
            sheets.save(new Sheet(sheetId));
        }
        long id = people.maxLocalId(sheetId) + 1;
        return people.save(new Person(sheetId, id, name.trim(), alpha, beta, gamma));
    }

    @Transactional
    /** Sets alpha; a real change is recorded in the audit as ALPHA_CHANGED id=.. from=.. to=... */
    public Optional<Person> setAlpha(String sheetId, long id, Integer alpha) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            Integer previous = p.getAlpha();
            p.setAlpha(alpha);
            if (!Objects.equals(previous, alpha)) {
                audit.record("ALPHA_CHANGED id=" + id + " from=" + previous + " to=" + alpha);
            }
            return p;
        });
    }

    @Transactional
    public Optional<Person> setBeta(String sheetId, long id, Integer beta) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setBeta(beta);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setGamma(String sheetId, long id, Integer gamma) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setGamma(gamma);
            return p;
        });
    }

    /** Sets the patrons (other people on the same sheet) by their id on that sheet; an empty list clears them. Refuses oneself or an unknown person. */
    @Transactional
    public Optional<Person> setPatrons(String sheetId, long id, Collection<Long> patronIds) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            Set<Person> patrons = new HashSet<>();
            for (Long patronId : patronIds) {
                if (patronId == id) {
                    throw new IllegalArgumentException("a person cannot be their own patron");
                }
                patrons.add(people.findBySheetIdAndLocalId(sheetId, patronId)
                        .orElseThrow(() -> new IllegalArgumentException("no person " + patronId + " on this sheet")));
            }
            p.setPatrons(patrons);
            return p;
        });
    }
}
